PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','manager','sales','warehouse','finance','viewer')),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sequences(prefix TEXT PRIMARY KEY,n INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS partners(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('customer','supplier','both')),contact TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',tax_id TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',payment_days INTEGER NOT NULL DEFAULT 30,credit_limit INTEGER NOT NULL DEFAULT 0,owner_id INTEGER REFERENCES users(id),notes TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS warehouses(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,sku TEXT UNIQUE NOT NULL,name TEXT NOT NULL,spec TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT '',unit TEXT NOT NULL DEFAULT '個',barcode TEXT NOT NULL DEFAULT '',price INTEGER NOT NULL DEFAULT 0 CHECK(price>=0),cost INTEGER NOT NULL DEFAULT 0 CHECK(cost>=0),safety_qty INTEGER NOT NULL DEFAULT 0 CHECK(safety_qty>=0),supplier_id INTEGER REFERENCES partners(id),active INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS product_barcode ON products(barcode) WHERE barcode<>'';
CREATE TABLE IF NOT EXISTS prices(id INTEGER PRIMARY KEY,partner_id INTEGER NOT NULL REFERENCES partners(id),product_id INTEGER NOT NULL REFERENCES products(id),price INTEGER NOT NULL CHECK(price>=0),UNIQUE(partner_id,product_id));
CREATE TABLE IF NOT EXISTS stocks(product_id INTEGER NOT NULL REFERENCES products(id),warehouse_id INTEGER NOT NULL REFERENCES warehouses(id),qty INTEGER NOT NULL DEFAULT 0 CHECK(qty>=0),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=qty),value INTEGER NOT NULL DEFAULT 0 CHECK(value>=0),PRIMARY KEY(product_id,warehouse_id));
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY,no TEXT UNIQUE NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('quote','order','purchase')),partner_id INTEGER NOT NULL REFERENCES partners(id),warehouse_id INTEGER NOT NULL REFERENCES warehouses(id),owner_id INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'draft',date TEXT NOT NULL,due_date TEXT NOT NULL,valid_until TEXT NOT NULL DEFAULT '',tax_mode TEXT NOT NULL DEFAULT 'exclusive' CHECK(tax_mode IN ('exclusive','inclusive','none')),tax_bp INTEGER NOT NULL DEFAULT 500 CHECK(tax_bp BETWEEN 0 AND 10000),net INTEGER NOT NULL,tax INTEGER NOT NULL,total INTEGER NOT NULL,notes TEXT NOT NULL DEFAULT '',shipping_address TEXT NOT NULL DEFAULT '',partner_snapshot TEXT NOT NULL,source_id INTEGER UNIQUE REFERENCES documents(id),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS document_lines(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES documents(id),product_id INTEGER NOT NULL REFERENCES products(id),sku TEXT NOT NULL,name TEXT NOT NULL,spec TEXT NOT NULL,unit TEXT NOT NULL,qty INTEGER NOT NULL CHECK(qty>0),price INTEGER NOT NULL CHECK(price>=0),discount_bp INTEGER NOT NULL DEFAULT 10000 CHECK(discount_bp BETWEEN 0 AND 10000),amount INTEGER NOT NULL CHECK(amount>=0),done_qty INTEGER NOT NULL DEFAULT 0 CHECK(done_qty BETWEEN 0 AND qty),notes TEXT NOT NULL DEFAULT '',UNIQUE(document_id,product_id));
CREATE TABLE IF NOT EXISTS fulfilments(id INTEGER PRIMARY KEY,no TEXT UNIQUE NOT NULL,document_id INTEGER NOT NULL REFERENCES documents(id),kind TEXT NOT NULL CHECK(kind IN ('shipment','receipt')),date TEXT NOT NULL,net INTEGER NOT NULL,tax INTEGER NOT NULL,total INTEGER NOT NULL,cost INTEGER NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fulfilment_lines(id INTEGER PRIMARY KEY,fulfilment_id INTEGER NOT NULL REFERENCES fulfilments(id),document_line_id INTEGER NOT NULL REFERENCES document_lines(id),product_id INTEGER NOT NULL REFERENCES products(id),qty INTEGER NOT NULL CHECK(qty>0),amount INTEGER NOT NULL,cost INTEGER NOT NULL,returned_qty INTEGER NOT NULL DEFAULT 0 CHECK(returned_qty BETWEEN 0 AND qty));
CREATE TABLE IF NOT EXISTS open_items(id INTEGER PRIMARY KEY,fulfilment_id INTEGER NOT NULL UNIQUE REFERENCES fulfilments(id),kind TEXT NOT NULL CHECK(kind IN ('receivable','payable')),partner_id INTEGER NOT NULL REFERENCES partners(id),amount INTEGER NOT NULL CHECK(amount>=0),paid INTEGER NOT NULL DEFAULT 0 CHECK(paid BETWEEN 0 AND amount),due_date TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,no TEXT UNIQUE NOT NULL,open_item_id INTEGER NOT NULL REFERENCES open_items(id),amount INTEGER NOT NULL CHECK(amount>0),method TEXT NOT NULL,date TEXT NOT NULL,reference TEXT NOT NULL DEFAULT '',created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stock_moves(id INTEGER PRIMARY KEY,no TEXT NOT NULL,product_id INTEGER NOT NULL REFERENCES products(id),warehouse_id INTEGER NOT NULL REFERENCES warehouses(id),qty INTEGER NOT NULL,value INTEGER NOT NULL,kind TEXT NOT NULL,reference TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS accounts(code TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('asset','liability','equity','revenue','expense')));
CREATE TABLE IF NOT EXISTS journals(id INTEGER PRIMARY KEY,no TEXT UNIQUE NOT NULL,date TEXT NOT NULL,memo TEXT NOT NULL,reference TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS journal_lines(id INTEGER PRIMARY KEY,journal_id INTEGER NOT NULL REFERENCES journals(id),account TEXT NOT NULL REFERENCES accounts(code),debit INTEGER NOT NULL DEFAULT 0 CHECK(debit>=0),credit INTEGER NOT NULL DEFAULT 0 CHECK(credit>=0),CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)));
CREATE TABLE IF NOT EXISTS boms(id INTEGER PRIMARY KEY,product_id INTEGER UNIQUE NOT NULL REFERENCES products(id),name TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS bom_lines(id INTEGER PRIMARY KEY,bom_id INTEGER NOT NULL REFERENCES boms(id),product_id INTEGER NOT NULL REFERENCES products(id),qty INTEGER NOT NULL CHECK(qty>0),UNIQUE(bom_id,product_id));
CREATE TABLE IF NOT EXISTS work_orders(id INTEGER PRIMARY KEY,no TEXT UNIQUE NOT NULL,product_id INTEGER NOT NULL REFERENCES products(id),warehouse_id INTEGER NOT NULL REFERENCES warehouses(id),qty INTEGER NOT NULL CHECK(qty>0),status TEXT NOT NULL DEFAULT 'draft',bom_snapshot TEXT NOT NULL,cost INTEGER NOT NULL DEFAULT 0,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS returns(id INTEGER PRIMARY KEY,no TEXT UNIQUE NOT NULL,fulfilment_id INTEGER NOT NULL REFERENCES fulfilments(id),net INTEGER NOT NULL,tax INTEGER NOT NULL,total INTEGER NOT NULL,cost INTEGER NOT NULL,reason TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS return_lines(id INTEGER PRIMARY KEY,return_id INTEGER NOT NULL REFERENCES returns(id),fulfilment_line_id INTEGER NOT NULL REFERENCES fulfilment_lines(id),qty INTEGER NOT NULL CHECK(qty>0));
CREATE TABLE IF NOT EXISTS loans(id INTEGER PRIMARY KEY,no TEXT UNIQUE NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('out','in')),partner_id INTEGER NOT NULL REFERENCES partners(id),product_id INTEGER NOT NULL REFERENCES products(id),warehouse_id INTEGER NOT NULL REFERENCES warehouses(id),qty INTEGER NOT NULL CHECK(qty>0),returned_qty INTEGER NOT NULL DEFAULT 0 CHECK(returned_qty BETWEEN 0 AND qty),cost INTEGER NOT NULL,due_date TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activities(id INTEGER PRIMARY KEY,partner_id INTEGER NOT NULL REFERENCES partners(id),title TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',next_date TEXT NOT NULL DEFAULT '',owner_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requests(key TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES users(id),fingerprint TEXT NOT NULL,response TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(key,user_id));
CREATE TABLE IF NOT EXISTS imports(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'preview',summary TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS document_links(source_id INTEGER NOT NULL REFERENCES documents(id),target_id INTEGER NOT NULL UNIQUE REFERENCES documents(id),kind TEXT NOT NULL,PRIMARY KEY(source_id,target_id));
CREATE TABLE IF NOT EXISTS inventory_counts(id INTEGER PRIMARY KEY,no TEXT UNIQUE NOT NULL,warehouse_id INTEGER NOT NULL REFERENCES warehouses(id),status TEXT NOT NULL DEFAULT 'draft',snapshot_move_id INTEGER NOT NULL,notes TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,posted_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS inventory_count_lines(id INTEGER PRIMARY KEY,count_id INTEGER NOT NULL REFERENCES inventory_counts(id),product_id INTEGER NOT NULL REFERENCES products(id),expected_qty INTEGER NOT NULL CHECK(expected_qty>=0),actual_qty INTEGER NOT NULL CHECK(actual_qty>=0),UNIQUE(count_id,product_id));
CREATE INDEX IF NOT EXISTS idx_doc_kind ON documents(kind,status,date);
CREATE INDEX IF NOT EXISTS idx_doc_partner ON documents(partner_id,owner_id);
CREATE INDEX IF NOT EXISTS idx_moves ON stock_moves(product_id,warehouse_id,id);
CREATE INDEX IF NOT EXISTS idx_open ON open_items(kind,partner_id);
CREATE INDEX IF NOT EXISTS idx_audit ON audit(id DESC);
CREATE TRIGGER IF NOT EXISTS no_move_update BEFORE UPDATE ON stock_moves BEGIN SELECT RAISE(ABORT,'immutable stock ledger'); END;
CREATE TRIGGER IF NOT EXISTS no_move_delete BEFORE DELETE ON stock_moves BEGIN SELECT RAISE(ABORT,'immutable stock ledger'); END;
CREATE TRIGGER IF NOT EXISTS no_journal_update BEFORE UPDATE ON journals BEGIN SELECT RAISE(ABORT,'immutable journal'); END;
CREATE TRIGGER IF NOT EXISTS no_journal_delete BEFORE DELETE ON journals BEGIN SELECT RAISE(ABORT,'immutable journal'); END;
CREATE TRIGGER IF NOT EXISTS no_jline_update BEFORE UPDATE ON journal_lines BEGIN SELECT RAISE(ABORT,'immutable journal line'); END;
CREATE TRIGGER IF NOT EXISTS no_jline_delete BEFORE DELETE ON journal_lines BEGIN SELECT RAISE(ABORT,'immutable journal line'); END;
CREATE TRIGGER IF NOT EXISTS no_audit_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'immutable audit'); END;
CREATE TRIGGER IF NOT EXISTS no_audit_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'immutable audit'); END;
